et_result_len(); // \u691c\u51fa\u3055\u308c\u305f\u4eba\u6570\u3092\u53d7\u4fe1\n     if(len)\n     {\n       int time1 = millis() - tick;\n       Serial.print("\u51e6\u7406\u6642\u9593: ");\n       Serial.println(time1);\n       Serial.print("\u4eba\u6570: ");\n       Serial.println(len);\n       object_detection_t data;       // \u30c7\u30fc\u30bf\u53d6\u5f97\n\n       for (int i = 0; i < len; i++)\n       {\n          Serial.println("\u7d50\u679c: \u691c\u51fa\u6e08\u307f");\n          Serial.print("\u691c\u51fa\u3068\u8a08\u7b97\u4e2d: ");\n          Serial.println(i+1);\n          ai.get_result(i, (uint8_t*)&data, sizeof(object_detection_t)); // \u7d50\u679c\u53d6\u5f97\n\n          Serial.print("\u4fe1\u983c\u5ea6:");\n          Serial.print(data.confidence);\n          Serial.println();\n        }\n     }\n     else\n     {\n       Serial.println("\u8b58\u5225\u306a\u3057");\n     }\n    }\n    else\n    {\n      delay(1000);\n      Serial.println("\u547c\u3073\u51fa\u3057\u5931\u6557\u3002");\n    }\n  }\n  else\n  {\n    state == 0;\n  }\n}\n')),(0,l.yg)("p",null,"\u30b7\u30ea\u30a2\u30eb\u30e2\u30cb\u30bf\u30fc\u3092\u958b\u304d\u3001\u30dc\u30fc\u30ec\u30fc\u30c8\u3092115200\u306b\u8a2d\u5b9a\u3059\u308b\u3068\u3001\u4eba\u691c\u51fa\u306e\u7d50\u679c\u304c\u7d99\u7d9a\u7684\u306b\u8868\u793a\u3055\u308c\u307e\u3059\u3002\u540c\u6642\u306b\u3001\u30e2\u30b8\u30e5\u30fc\u30eb\u304c\u30ad\u30e3\u30d7\u30c1\u30e3\u3057\u305f\u753b\u50cf\u3082",(0,l.yg)("a",{parentName:"p",href:"https://vision-ai-demo.seeed.cn/"},"\u30a6\u30a7\u30d6\u30b5\u30a4\u30c8"),"\u306b\u8868\u793a\u3055\u308c\u307e\u3059\u3002\u6210\u529f\u3057\u305f\u51fa\u529b\u306f\u4ee5\u4e0b\u306e\u3088\u3046\u306b\u306a\u308a\u307e\u3059\u3002"),(0,l.yg)("div",{style:{textAlign:"center"}},(0,l.yg)("img",{src:"https://files.seeedstudio.com/wiki/Grove_AI_Module/GroveAI12.png",style:{width:400,height:"auto"}})),(0,l.yg)("p",null,(0,l.yg)("a",{parentName:"p",href:"https://vision-ai-demo.seeed.cn/"}